INSERT INTO course_quizzes (id,course_id,lesson_id,title,passing_percent,status) VALUES ('a512fefb-daf0-49a3-b39e-178838658e59',@course_id,'840c736f-94c8-4685-8350-98662d8f72a7','Data Engineering Fundamentals — Topic Check',70,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('5a976b2e-2002-444a-a036-267e592ad35a','a512fefb-daf0-49a3-b39e-178838658e59','What is the primary purpose of Data Engineering Fundamentals in a Data Engineering solution?','["To apply Data Engineering Fundamentals to solve the relevant data problem","To replace all validation and monitoring","To avoid storing any data","To remove the need for engineering design"]',0,'The lesson topic should be understood in terms of the data problem it solves.','EASY',0,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('dd0f9f32-f563-4fa4-97aa-bfdf791c016a','a512fefb-daf0-49a3-b39e-178838658e59','Which situation is the best fit for applying Data Engineering Fundamentals?','["A pipeline or platform scenario where Data Engineering Fundamentals directly addresses the requirement","A situation unrelated to data processing","Only a UI styling change","A task that requires no data or system behavior"]',0,'Choose the scenario where the lesson topic directly contributes to the data workflow.','EASY',1,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('05b5d927-a0ed-4950-bf1c-e110750d25dc','a512fefb-daf0-49a3-b39e-178838658e59','Which production concern matters most when implementing Data Engineering Fundamentals?','["Correctness, scale, failure handling and observability","Only the number of code lines","Only whether the first run succeeds","Ignoring operational behavior"]',0,'Production Data Engineering requires correctness plus operational reliability.','MEDIUM',2,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('62c439ff-8b3b-4c74-b848-effbc1907cac','a512fefb-daf0-49a3-b39e-178838658e59','How should Data Engineering Fundamentals be validated before production use?','["Test representative inputs, edge cases and expected outputs","Skip tests because production data is trusted","Validate only after a failure","Check only that the process started"]',0,'Validation should prove expected behavior for normal and edge cases.','MEDIUM',3,'published');
INSERT INTO quiz_questions (id,quiz_id,question_text,options_json,correct_option,explanation,difficulty,display_order,status) VALUES ('7a3a4aa7-230c-4cfa-9d31-8c84ef8532e0','a512fefb-daf0-49a3-b39e-178838658e59','What should an interview-ready explanation of Data Engineering Fundamentals include?','["Purpose, implementation, trade-offs, failure modes and a practical example","Only a one-line definition","Only the product name","Only memorized syntax"]',0,'An industry-ready answer connects the concept to implementation and trade-offs.','HARD',4,'published');
INSERT INTO course_quizzes (id,course_id,lesson_id,title,passing_percent,status) VALUES ('f93345a5-9396-4407-b38b-a3e819e31da0',@course_id,'3249f012-d8b1-42dc-9eb7-a61bc851cacb','What is Data Engineering? — Topic Check',70,'published');
